import math
n = int(input())
circles = []

class Point:
    def __init__(self, x, y):
        self.x = x
        self.y = y
    def sub(self, o):
        return Point(self.x - o.x, self.y - o.y)
    def moveAlongLine(self, line, length):
        return self.moveAlongVector(line.asVector(), length)
    def moveAlongVector(self, v, length):
        mag = math.hypot(v.x, v.y)
        if mag < 1e-15:
            return Point(self.x, self.y)
        return self.add(Point(v.x / mag, v.y / mag).mul(length))
    def add(self, o):
        return Point(self.x + o.x, self.y + o.y)
    def mul(self, f):
        return Point(self.x * f, self.y * f)
    def getAlpha(self):
        return Point(-self.y, self.x)
    def __eq__(self, o):
        if not isinstance(o, Point):
            return False
        return abs(self.x - o.x) < 1e-10 and abs(self.y - o.y) < 1e-10
    def __lt__(self, o):
        if abs(self.x - o.x) < 1e-10:
            return self.y < o.y
        return self.x < o.x

class Line:
    def __init__(self, from_point, to_point):
        self.from_point = from_point
        self.to = to_point
    def asVector(self):
        return self.to.sub(self.from_point)
    def length(self):
        return math.hypot(self.to.x - self.from_point.x, self.to.y - self.from_point.y)

class Circle:
    def __init__(self, x, y, r):
        self.center = Point(x, y)
        self.r = r
    @staticmethod
    def distance(a, b):
        return math.hypot(a.x - b.x, a.y - b.y)
    @staticmethod
    def isIntersect(a, b):
        d = Circle.distance(a.center, b.center)
        return d <= a.r + b.r + 1e-10 and d + 1e-10 >= abs(a.r - b.r)
    @staticmethod
    def isIntersect2(a, b):
        d = Circle.distance(a.center, b.center)
        return d < a.r + b.r and d > abs(a.r - b.r)
    @staticmethod
    def intersectAt(a, b, set_points):
        if not Circle.isIntersect(a, b):
            return
        line = Line(a.center, b.center)
        d = Circle.distance(a.center, b.center)
        midDist = (d * d - b.r * b.r + a.r * a.r) / (2 * d)
        mid = a.center.moveAlongLine(line, midDist)
        alpha = line.asVector().getAlpha()
        height = math.sqrt(a.r * a.r - midDist * midDist)
        p1 = mid.moveAlongVector(alpha, height)
        p2 = mid.moveAlongVector(alpha, -height)
        set_points.add(p1)
        if not p2 == p1:
            set_points.add(p2)

